#!/usr/bin/env python3
"""Generates line_break_table.h: GLib's Line_Break property table
(glib/gunibreak.h, which Pango's line breaking reads through
g_unichar_break_type) as compact numeric C tables, with GLib's
GUnicodeBreakType numbering (glib/gunicode.h).

usage: gen_line_break.py path/to/glib/glib > line_break_table.h
"""
import re
import sys

glib = sys.argv[1]
hdr = open(glib + '/gunicode.h').read()
body = hdr[hdr.index('typedef enum\n{\n  G_UNICODE_BREAK_MANDATORY'):]
body = body[:body.index('} GUnicodeBreakType;')]
values = {}
n = 0
for m in re.finditer(r'^\s*(G_UNICODE_BREAK_[A-Z_]+)\s*(?:GLIB_[A-Z_0-9]+\s*)?(?:=\s*(G_UNICODE_BREAK_[A-Z_]+))?\s*,?', body, re.M):
    name, alias = m.group(1), m.group(2)
    if alias:
        values[name] = values[alias]
    else:
        values[name] = n
        n += 1
tab = open(glib + '/gunibreak.h').read()
version = re.search(r'G_UNICODE_DATA_VERSION "([^"]+)"', tab).group(1)
maxidx = int(re.search(r'G_UNICODE_MAX_TABLE_INDEX (\d+)', tab).group(1))
last1 = int(re.search(r'G_UNICODE_LAST_CHAR_PART1 (0x[0-9A-Fa-f]+)', tab).group(1), 16)
data_src = tab[tab.index('break_property_data[][256] = {'):tab.index('};', tab.index('break_property_data'))]
pages = []
for p in re.findall(r'\{ /\* page \d+, index \d+ \*/(.*?)\}', data_src, re.S):
    vals = [values[v] for v in re.findall(r'G_UNICODE_BREAK_[A-Z_]+', p)]
    assert len(vals) == 256
    pages.append(vals)

def table(name):
    src = tab[tab.index(name + '['):]
    src = src[src.index('{') + 1:src.index('};')]
    out = []
    for e in src.split(','):
        e = re.sub(r'/\*.*?\*/', '', e).strip()
        if not e:
            continue
        m = re.match(r'(G_UNICODE_BREAK_[A-Z_]+) \+ G_UNICODE_MAX_TABLE_INDEX', e)
        out.append(0x8000 | values[m.group(1)] if m else int(e))
    return out

t1 = table('break_property_table_part1')
t2 = table('break_property_table_part2')

def prop(c):
    if c <= last1:
        e = t1[c >> 8]
    elif 0xE0000 <= c <= 0x10FFFF:
        e = t2[(c - 0xE0000) >> 8]
    else:
        return values['G_UNICODE_BREAK_UNKNOWN']
    return e & 0x7FFF if e & 0x8000 else pages[e][c & 0xFF]

# Blocks of 128 code points, deduplicated: smaller than GLib's 256-entry
# pages with uniform-page markers (35 KB instead of 54 KB).
B = 128
ranges = ((0, (last1 + 1) // B), (0xE0000 // B, 0x110000 // B))
blocks, index = {}, []
for lo, hi in ranges:
    idx = []
    for b in range(lo, hi):
        blk = tuple(prop(c) for c in range(b * B, b * B + B))
        idx.append(blocks.setdefault(blk, len(blocks)))
    index.append(idx)
itype = 'uint8_t' if len(blocks) <= 256 else 'uint16_t'

w = sys.stdout.write
w('/* GLib %s\'s Line_Break property table (glib/gunibreak.h), the data\n' % version)
w(' * Pango\'s line breaking reads through g_unichar_break_type, as compact\n')
w(' * numeric tables. Generated by gen_line_break.py; do not edit. Values:\n')
w(' * GLib\'s GUnicodeBreakType.\n *\n')
w(' * SPDX-License-Identifier: LGPL-2.1-or-later AND Unicode-3.0 */\n\n')
w('#define BUI_LB_LAST_PART1 0x%X\n\n' % last1)
w('enum {\n')
seen = set()
for name, v in sorted(values.items(), key=lambda kv: (kv[1], kv[0])):
    if 'PARANTHESIS' in name:
        continue
    w('  BUI_LB_%s = %d,\n' % (name[len('G_UNICODE_BREAK_'):], v))
w('};\n\n')
w('static const uint8_t bui_lb_blocks[%d][%d] = {\n' % (len(blocks), B))
for blk in sorted(blocks, key=blocks.get):
    w('  {')
    for i in range(0, B, 32):
        w('\n    ' + ','.join(str(v) for v in blk[i:i + 32]) + ',')
    w('\n  },\n')
w('};\n\n')
for name, idx in (('bui_lb_index1', index[0]), ('bui_lb_index2', index[1])):
    w('static const %s %s[%d] = {' % (itype, name, len(idx)))
    for i in range(0, len(idx), 32):
        w('\n  ' + ','.join(str(v) for v in idx[i:i + 32]) + ',')
    w('\n};\n\n')
w('''static int bui_lb_type(uint32_t c)
{
  if (c <= BUI_LB_LAST_PART1) {
    return bui_lb_blocks[bui_lb_index1[c >> 7]][c & 0x7F];
  }
  if (c >= 0xE0000 && c <= 0x10FFFF) {
    return bui_lb_blocks[bui_lb_index2[(c - 0xE0000) >> 7]][c & 0x7F];
  }
  return BUI_LB_UNKNOWN;
}
''')
